/* aesthetic status v2.21.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ok: #15714b;
  --ae-warn: #8a5f32;
  --ae-err: #a84138;
  --ae-ok-dark: #6fd2a8;
  --ae-warn-dark: #c49d72;
  --ae-err-dark: #e58379;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ok: var(--ae-ok-dark);
    --ae-warn: var(--ae-warn-dark);
    --ae-err: var(--ae-err-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

:root.dark,
:root[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ok: var(--ae-ok-dark);
  --ae-warn: var(--ae-warn-dark);
  --ae-err: var(--ae-err-dark);
}

.ae-icon {
width: 1.2em;
  height: 1.2em;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
  vertical-align: -0.2em;
}

.ae-ok {
color: var(--ae-ok);
}

.ae-warn {
color: var(--ae-warn);
}

.ae-err {
color: var(--ae-err);
}
